parameters.jsCode:
const items = ((($json.data || {}).items_page_by_column_values) || {}).items || [];
const gmail = $('Build Thread Lookup').item.json._gmail;
if (!items.length) {
  // No matching outreach thread, drop
  return [];
}
const lead = items[0];
function colVal(item, colId) { const c = (item.column_values || []).find(c => c.id === colId); return c ? (c.text || '') : ''; }
const status = colVal(lead, $env.MONDAY_COL_LEAD_STATUS);
if (status === 'Qualified') {
  // Already handled, drop
  return [];
}
// Parse sender name from From header ("Name <email@x>" or just email)
const from = gmail.from || '';
const senderName = (from.match(/^([^<]+?)\s*</) || [])[1] || from.split('@')[0];
const senderEmail = (from.match(/<([^>]+)>/) || [])[1] || from;
return [{ json: {
  leads_item_id: lead.id,
  lead_name: colVal(lead, $env.MONDAY_COL_LEAD_NAME) || lead.name,
  lead_email: colVal(lead, $env.MONDAY_COL_LEAD_EMAIL) || senderEmail,
  sender_name: senderName.trim(),
  sender_email: senderEmail.trim(),
  thread_id: gmail.threadId,
  message_id: gmail.messageId,
  subject: gmail.subject,
  reply_text: gmail.body || gmail.snippet || '',
  reply_snippet: (gmail.body || gmail.snippet || '').substring(0, 200)
}}];

