  const text = `NEW REPLY from ${ctx.sender_name} (${ctx.sender_email})\n\nTHEIR MESSAGE:\n${ctx.reply_text}\n\nDRAFTED RESPONSE:\n${draft}\n\nReact with :white_check_mark: to send as is\nReply to this message with your edited version to send your edit instead\nReact with :x: to skip and handle manually`;
  return JSON.stringify({
    channel: $env.SLACK_APPROVAL_CHANNEL_ID,
    text,
    metadata: {
      event_type: 'outreach_approval',
      event_payload: {
        gmail_thread_id: ctx.thread_id,
        gmail_message_id: ctx.message_id,
        lead_email: ctx.lead_email,
        sender_email: ctx.sender_email,
        sender_name: ctx.sender_name,
        leads_item_id: ctx.leads_item_id,
        subject: ctx.subject,
        claude_draft: draft
      }
    }
  });
})() }}
